def tensors_loss(w,b,P,L,U,y,tail,aux,reg):
    logits=P@w+b;gate=torch.sigmoid(logits);pred=L+gate*(U-L);weight=torch.where(y>=20,float(tail),torch.where(y>=12,float(np.sqrt(tail)),1.));target=(y>=20).double();positive=(len(y)-target.sum())/target.sum();loss=(torch.nn.functional.smooth_l1_loss(pred,y,beta=1,reduction='none')*weight).mean()+reg*(w*w).sum()
